4	namespace WPMedia\BackWPup\Tracking;
5	
6	use WPMedia\BackWPup\Adapters\OptionAdapter;
7	use WPMedia\BackWPup\Dependencies\WPMedia\Mixpanel\Optin;
8	use WPMedia\BackWPup\Dependencies\WPMedia\Mixpanel\TrackingPlugin as MixpanelTracking;
9	
10	if ( ! defined( 'ABSPATH' ) ) {
11		exit;
12	}
13	
14	class Tracking extends BaseTracking {
15		/**
16		 * Option Adapter instance.
17		 *
18		 * @var OptionAdapter
19		 */
20		private $option_adapter;
21	
22		/**
23		 * Tracking constructor.
24		 *
25		 * @param Optin            $optin Optin instance.
26		 * @param MixpanelTracking $mixpanel Mixpanel Tracking instance.
27		 * @param OptionAdapter    $option_adapter Option Adapter instance.
28		 */
29		public function __construct( Optin $optin, MixpanelTracking $mixpanel, OptionAdapter $option_adapter ) {
30			parent::__construct( $optin, $mixpanel );
31			$this->option_adapter = $option_adapter;
32		}
33	
34		/**
35		 * Update the Mixpanel opt-in setting.
36		 *
37		 * @return void
38		 */
39		public function update_setting(): void {
40			if ( ! isset( $_POST['_wpnonce'] ) || ! wp_verify_nonce( sanitize_key( $_POST['_wpnonce'] ), 'backwpup_page' ) ) {
41				return;
42			}
43	
44			if ( get_site_option( 'backwpup_onboarding', false ) ) {
45				return;
46			}
47	
48			$value = isset( $_POST['mixpanel'] ) ? 1 : 0;
49	
50			if ( 0 === $value ) {
51				if ( $this->optin->is_enabled() ) {
52					$this->optin->disable();
53				}
54	
55				return;
56			}
57	
58			if ( 1 === $value ) {
59				$this->optin->enable();
60			}
61		}
62	
63		/**
64		 * Track an opt-in change event.
65		 *
66		 * @param bool $optin The new opt-in value.
67		 *
68		 * @return void
69		 */
70		public function track_optin_change( $optin ): void {
71			$user = wp_get_current_user();
72	
73			$this->mixpanel->identify( $user->user_email );
74			$this->mixpanel->track_optin( $optin );
75		}
76	
77		/**
78		 * Track the beta opt-in change event.
79		 *
80		 * @param int $optin The new opt-in value.
81		 *
82		 * @return void
83		 */
84		public function track_beta_optin_change( $optin ): void {
85			if ( ! $this->optin->is_enabled() ) {
86				return;
87			}
88	
89			$user = wp_get_current_user();
90	
91			$this->mixpanel->identify( $user->user_email );
92	
93			$properties                  = $this->get_default_event_properties();
94			$properties['opt_in_status'] = (bool) $optin;
95	
96			$this->mixpanel->track(
97				'WordPress Plugin Beta Opt-in Changed',
98				$properties
99			);
100		}
101	
102		/**
103		 * Track the addition of a new job.
104		 *
105		 * @param array $job The job data.
106		 *
107		 * @return void
108		 */
109		public function track_add_job( $job ) {
110			if ( ! $this->optin->is_enabled() ) {
111				return;
112			}
113	
114			$user = wp_get_current_user();
115	
116			$this->mixpanel->identify( $user->user_email );
117	
118			$this->mixpanel->track(
119				'Scheduled Backup Job Created',
120				array_merge( $this->get_default_event_properties(), $this->get_event_properties( $job, true ) )
121			);
122		}
123	
124		/**
125		 * Track the deletion of a job.
126		 *
127		 * @param int $job_id The ID of the job to delete.
128		 *
129		 * @return void
130		 */
131		public function track_delete_job( $job_id ) {
132			if ( ! $this->optin->is_enabled() ) {
133				return;
134			}
135	
136			$user = wp_get_current_user();
137	
138			$this->mixpanel->identify( $user->user_email );
139	
140			$job = $this->option_adapter->get_job( $job_id );
141	
142			$this->mixpanel->track(
143				'Scheduled Backup Job Deleted',
144				array_merge( $this->get_default_event_properties(), $this->get_event_properties( $job ) )
145			);
146		}
147	
148		/**
149		 * Track the start of a job.
150		 *
151		 * @param array  $job The Job data.
152		 * @param string $trigger The backup trigger.
153		 *
154		 * @return void
155		 */
156		public function track_start_job( array $job, $trigger ): void {
157			if ( ! $this->optin->can_track() ) {
158				return;
159			}
160	
161			$user       = wp_get_current_user();
162			$email      = $user->user_email ?? $job['mailaddresslog'];
163			$properties = array_merge( $this->get_default_event_properties(), $this->get_backup_event_properties( $job ) );
164	
165			$this->mixpanel->identify( $email );
166	
167			$properties['backup_trigger'] = $trigger;
168	
169			// @todo Refactor it when the Mixpanel library supports system capabilities.
170			$this->with_system_cap(
171					function () use ( $job, $properties ) {
172						$this->mixpanel->track(
173						'Scheduled Backup Job Started',
174						$properties,
175						'bwu_mixpanel_send_event'
176						);
177					}
178				);
179		}
180	
181		/**
182		 * Track end of job.
183		 *
184		 * @param int    $job_id The job id.
185		 * @param array  $job_details The status of the job.
186		 * @param string $trigger Backup trigger.
187		 *
188		 * @return void
189		 */
190		public function track_end_job( $job_id, array $job_details, $trigger ): void {
191			if ( ! $this->optin->can_track() ) {
192				return;
193			}
194	
195			$job   = $this->option_adapter->get_job( $job_id );
196			$user  = wp_get_current_user();
197			$email = $user->user_email ?? $job['mailaddresslog'];
198	
199			$this->mixpanel->identify( $email );
200			$status = true;
201	
202			$properties                   = array_merge( $this->get_default_event_properties(), $this->get_backup_event_properties( $job, true ) );
203			$properties['backup_trigger'] = $trigger;
204	
205			foreach ( $job_details as $job ) {
206				$properties[ 'storage_' . $job['storage'] ] = [
207					'storage'       => $job['storage'],
208					'status'        => $job['status'],
209					'error_code'    => $job['error_code'],
210					'error_message' => $job['error_message'],
211				];
212	
213				if ( 'completed' !== $job['status'] ) {
214					$status = false;
215				}
216			}
217	
218			$properties['job_completed'] = $status;
219	
220			// @todo Refactor it when the Mixpanel library supports system capabilities.
221			$this->with_system_cap(
222					function () use ( $properties ) {
223						$this->mixpanel->track(
224						'Scheduled Backup Job Ended',
225						$properties,
226						'bwu_mixpanel_send_event'
227						);
228					}
229				);
230		}
231	
232		/**
233		 * Get backup event properties.
234		 *
235		 * @param array $job The job data.
236		 * @param bool  $included_job_completion Include job completion info.
237		 *
238		 * @return array
239		 */
240		private function get_backup_event_properties( array $job, bool $included_job_completion = false ): array {
241			$legacy_job = ! empty( $job['legacy'] );
242	
243			$properties = [
244				'legacy_job' => $legacy_job,
245			];
246	
247			if ( $included_job_completion ) {
248				$properties['duration'] = $job['lastruntime'];
