282		/**
283		 * Check if the job has manual exclusions.
284		 *
285		 * @param array $job The job data.
286		 *
287		 * @return bool
288		 */
289		private function has_manual_exclude( array $job ): bool {
290			$defaults  = $this->option_adapter->defaults_job();
291			$job_types = $job['type'] ?? [];
292	
293			// Define exclusions by backup type.
294			$database_exclusions = [
295				'dbdumpexclude',
296			];
297	
298			$file_exclusions = [
299				'backuprootexcludedirs',
300				'backupcontentexcludedirs',
301				'backuppluginsexcludedirs',
302				'backupthemesexcludedirs',
303				'backupuploadsexcludedirs',
304				'fileexclude',
305				'backuproot',
306				'backupuploads',
307				'backupthemes',
308				'backupplugins',
309				'backupcontent',
310				'backupspecialfiles',
311			];
312	
313			$exclusions = [];
314	
315			// Only check database exclusions if DBDUMP is in job types.
316			if ( in_array( 'DBDUMP', $job_types, true ) ) {
317				$exclusions = array_merge( $exclusions, $database_exclusions );
318			}
319	
320			// Only check file exclusions if FILE is in job types.
321			if ( in_array( 'FILE', $job_types, true ) ) {
322				$exclusions = array_merge( $exclusions, $file_exclusions );
323			}
324	
325			foreach ( $exclusions as $exclusion ) {
326				if ( is_array( $job[ $exclusion ] ) && is_array( $defaults[ $exclusion ] ) ) {
327					if ( ! empty( array_diff( $job[ $exclusion ], $defaults[ $exclusion ] ) ) ) {
328						return true;
329					}
330				} elseif ( $job[ $exclusion ] !== $defaults[ $exclusion ] ) {
331					return true;
332				}
333			}
334	
335			return false;
336		}
