386		/**
387		 * Run a callback with the system capability to send events.
388		 * The system capability is only granted to the callback and removed afterwards.
389		 * The capability is only granted if the current capability check is for sending events with no user (0) and to the capability bwu_mixpanel_send_event.
390		 * The capability is granted via the 'user_has_cap' filter.
391		 * This is to allow sending events from contexts where no user is logged in, such as cron jobs.
392		 *
393		 * @param callable $cb The callback to run.
394		 *
395		 * @return void
396		 */
397		private function with_system_cap( callable $cb ) {
398			$grant_cap = static function ( $allcaps, $caps, $args ) {
399				if ( isset( $args[0], $args[1] ) && 'bwu_mixpanel_send_event' === $args[0] ) {
400					$allcaps['bwu_mixpanel_send_event'] = true;
401				}
402				return $allcaps;
403			};
404	
405			add_filter( 'user_has_cap', $grant_cap, 10, 3 );
406			try {
407				$cb();
408			} finally {
409				remove_filter( 'user_has_cap', $grant_cap, 10 );
410			}
411		}
