106		/**
107		 * Sanitize input parameters for tracking.
108		 *
109		 * Removes sensitive data and limits array size to prevent tracking bloat.
110		 *
111		 * @param array $params Input parameters.
112		 *
113		 * @return array
114		 */
115		protected function sanitize_input_params( array $params ): array {
116			// List of sensitive keys to exclude.
117			$sensitive_keys = [
118				'password',
119				'api_key',
120				'secret',
121				'token',
122				'auth',
123				'credentials',
124				'email',
125			];
126	
127			$sanitized = [];
128	
129			foreach ( $params as $key => $value ) {
130				// Skip sensitive keys.
131				$key_lower = strtolower( (string) $key );
132				foreach ( $sensitive_keys as $sensitive ) {
133					if ( false !== strpos( $key_lower, $sensitive ) ) {
134						continue 2;
135					}
136				}
137	
138				// Limit array depth.
139				if ( is_array( $value ) ) {
140					$sanitized[ $key ] = '[array:' . count( $value ) . ']';
141				} elseif ( is_object( $value ) ) {
142					$sanitized[ $key ] = '[object:' . get_class( $value ) . ']';
143				} else {
144					$sanitized[ $key ] = $value;
145				}
146			}
147	
148			return $sanitized;
149		}
